using UnityEngine;
namespace DiwaliGameplay {
public class SweetPlacementGhost : MonoBehaviour {
 GrabbableItem source;Transform visual;Material material;
 public void Show(GrabbableItem item,Transform target,bool visible,bool close=false,Vector3? previewScale=null){if(!visible){if(visual)visual.gameObject.SetActive(false);return;}if(source!=item){if(visual)Destroy(visual.gameObject);if(material)Destroy(material);source=item;visual=new GameObject("Valid placement preview").transform;visual.SetParent(transform,false);var shader=Shader.Find("Universal Render Pipeline/Unlit")??Shader.Find("Sprites/Default");material=new Material(shader);material.SetColor("_BaseColor",new Color(.35f,1,.65f,.2f));material.color=new Color(.35f,1,.65f,.2f);material.SetFloat("_Surface",1);material.SetFloat("_ZWrite",0);material.SetFloat("_SrcBlend",(float)UnityEngine.Rendering.BlendMode.SrcAlpha);material.SetFloat("_DstBlend",(float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=3000;foreach(var mf in item.GetComponentsInChildren<MeshFilter>(true)){if(!mf.sharedMesh||mf.GetComponentInParent<GrabbableItem>()!=item)continue;var go=new GameObject("Placement ghost mesh",typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(visual,false);go.transform.localPosition=item.transform.InverseTransformPoint(mf.transform.position);go.transform.localRotation=Quaternion.Inverse(item.transform.rotation)*mf.transform.rotation;go.transform.localScale=new Vector3(mf.transform.lossyScale.x/item.transform.lossyScale.x,mf.transform.lossyScale.y/item.transform.lossyScale.y,mf.transform.lossyScale.z/item.transform.lossyScale.z);go.GetComponent<MeshFilter>().sharedMesh=mf.sharedMesh;var materials=new Material[mf.sharedMesh.subMeshCount];for(int i=0;i<materials.Length;i++)materials[i]=material;go.GetComponent<MeshRenderer>().sharedMaterials=materials;}}
 var color=close?new Color(.35f,1,.65f,.28f):new Color(1,.65f,.2f,.28f);material.SetColor("_BaseColor",color);material.color=color;visual.gameObject.SetActive(true);visual.SetPositionAndRotation(target.position,target.rotation);visual.localScale=previewScale??item.transform.localScale;}
 void OnDestroy(){if(material)Destroy(material);}
}
}
